fn.magicSlotSwipe:
function magicSlotSwipe(fingers,dir){
 const row=MAGIC_SLOT_MAP[fingers];if(!row||row[dir]===undefined)return false;
 const i=row[dir];const sp=SPELLS[i];
 safeFn(()=>UI.natStep("ui_select",0.5,0.88+i*0.045));
 if(!sp){narrate(`Слот ${i+1} пуст.`,{interrupt:true});return true;}
 narrate(`Слот ${i+1}: ${sp.n}.`,{interrupt:true});
 safeFn(()=>castSpell(i));
 return true;}

fn.safeOpenMagicPanel:
function safeOpenMagicPanel(){
 try{
  let m=document.getElementById("magicPanel");
  if(!m){
   m=document.createElement("div");m.id="magicPanel";m.className="overlay";m.hidden=true;m.setAttribute("role","dialog");m.setAttribute("aria-modal","true");m.setAttribute("aria-label","Панель магии");
   m.innerHTML='<div class="sheet"><h2>Магия</h2><div id="magicSlots" class="list"></div><p>Двенадцать слотов по свайпам: один палец — 1–4, два пальца — 5–8, три пальца — 9–12 (вверх, вправо, влево, вниз). Двойное касание четырьмя пальцами — закрыть.</p><button type="button" data-magic-close>Закрыть</button></div>';
   document.body.appendChild(m);m.querySelector('[data-magic-close]').addEventListener('click',()=>closeMagicPanel());
  }
  const list=m.querySelector('#magicSlots'); list.innerHTML='';
  const known=Array.isArray(G.spells)?G.spells:[];
  safeFn(()=>registerCustomSpells());
  for(let i=0;i<Math.max(12,SPELLS.length);i++){
   const sp=SPELLS[i]||{n:`Слот ${i+1}`,cost:0};const b=document.createElement('button');b.type='button';b.className='item';b.dataset.magicIndex=i;
   /* Резонанс называется до траты: незрячему игроку важно услышать, во что
      обойдётся чужая стихия, прежде чем он её тронет. */
   const рез=(SPELLS[i]&&known.includes(sp.n))?safeFn(()=>" Созвучие: "+Resonance.слово(sp)+".",""):"";
   b.dataset.speak=`Слот ${i+1}: ${sp.n}. Мана ${sp.cost}.${рез}`;
   b.textContent=`${i+1}. ${sp.n}${known.includes(sp.n)?'':' (не изучено)'}`;
   b.addEventListener('click',()=>{try{castSpell(i);}catch(e){narrate('Не удалось применить заклинание.');}});list.appendChild(b);
  }
  /* Вложенные чары висят тут же, за слотами: жезл нужен в подземелье, а
     не в башне, где его сделали. */
  safeFn(()=>{
   const мои=chargedList();
   мои.forEach((it,k)=>{
    const c=CARRIER_BY_ID[it.вид];if(!c||!c.заряды)return;
    const b=document.createElement('button');b.type='button';b.className='item';
    b.dataset.speak=chargedLine(it)+" Двойное касание — применить.";
    b.textContent=`${chargedName(it)} — ${it.заряд} из ${it.макс}`;
    b.addEventListener('click',()=>{try{chargedUse(k);safeOpenMagicPanel();}catch(e){narrate('Не удалось применить вещь.');}});
    list.appendChild(b);});});
  m.hidden=false;m.setAttribute('aria-hidden','false');UI.open();const first=list.querySelector('button');if(first)first.focus();narrate('Панель магии открыта. '+magicSlotHint());
 }catch(e){try{console.error('Magic panel recovery',e);narrate('Панель магии временно недоступна.');}catch(x){}}
}

fn.buyCountButtons:
function buyCountButtons(price,cmd,name){
 const цена=Math.max(1,Number(price)||1),золото=Number(G.gold)||0,макс=Math.floor(золото/цена);
 if(макс<1)return `<button data-cmd="${cmd(1)}" data-speak="Не хватает золота: ${name} стоит ${цена}, у вас ${золото}.">Не хватает золота (${цена})</button>`;
 return [1,5,10].filter(k=>k<=макс).map(k=>`<button data-cmd="${cmd(k)}" data-speak="Купить ${k} — ${name} — за ${цена*k} золота.">Купить ${k} (${цена*k})</button>`).join("")
  +(макс>10?`<button data-cmd="${cmd(макс)}" data-speak="Купить на всё золото: ${макс} — ${name} — за ${цена*макс} золота.">На всё золото: ${макс} (${цена*макс})</button>`:"");}

grimsay:
grimsay(i){const r=safeFn(()=>grimAt(Number(i)),null);
  if(!r){narrate("Такого заклинания в гримуаре нет.");return;}
  safeFn(()=>Bank.play(r.голос||"magic_shimmer",{gain:0.45,maxSec:3}));
  narrate(safeFn(()=>grimLine(r),r.n),{pri:1,key:"grim"});},

gestpick:
gestpick(arg){
  const p=String(arg||"").split("~");
  const s=GEST_SHAPE_BY_ID[p[0]];
  if(!s){narrate("Такой фигуры нет.");return;}
  if(p[1]){gestBind(p[0],p[1]);safeFn(()=>renderGestBind());return;}
  /* Без второго довода — называем, что сейчас на этой фигуре, и предлагаем
     список действий тем же окном действий. */
  narrate(gestLine(p[0]),{interrupt:true});},
